<?php
namespace App\Http\Controllers\Web;use App\Http\Controllers\Controller;use App\Models\Reconciliation;use App\Services\Reconciliation\Governance\ReconciliationApprovalService;use Illuminate\Http\Request;
class ApprovalQueueController extends Controller {public function index(){return view('reconciliation.approvals',['items'=>Reconciliation::query()->with('items')->where('status','pending_review')->latest()->paginate(25)]);}public function approve(Request $r,Reconciliation $reconciliation,ReconciliationApprovalService $s){$d=$r->validate(['note'=>'nullable|string|max:500']);$s->approve($reconciliation,$r->user()->id,$d['note']??null);return back()->with('success','Conciliación aprobada por el revisor.');}public function reject(Request $r,Reconciliation $reconciliation,ReconciliationApprovalService $s){$d=$r->validate(['note'=>'required|string|min:5|max:500']);$s->reject($reconciliation,$r->user()->id,$d['note']);return back()->with('warning','Conciliación rechazada.');}}
